import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2018-10-18","description":"","frontmatter":{"title":"Ceph Performance Meeting 2018-10-18","date":"2018-10-18T00:00:00.000Z","updated":"2018-10-19T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RocksDB","调试信息"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Performance_Meeting_2018-10-18.md","filePath":"posts/2018/Ceph_Performance_Meeting_2018-10-18.md","lastUpdated":1780459816000}'),s={name:"posts/2018/Ceph_Performance_Meeting_2018-10-18.md"};function r(n,l,a,p,g,u){return i(),t("div",null,[...l[0]||(l[0]=[o("<p>会议纪要：</p><p><strong>会议时间</strong>： 2018年10月18日 <strong>参会人员</strong>： Nick、Radek、Sage、Josh、Greg、Steve、Angie、Peter、Doug等 <strong>会议主题</strong>： Ceph分布式存储项目开发进展及讨论 <strong>关键细节</strong>：</p><ul><li><strong>Pull Requests</strong>： <ul><li>Radek提交了一个针对边界代码的优化请求，通过减少容器分配的内存需求来提高效率。</li><li>Radek还提交了一个针对编译器优化的请求，特别是对于Ceph列表中空数据部分的优化。</li><li>Sage合并了Radek提交的字符串处理代码。</li><li>Radek提出了一个关于调试信息的讨论，包括是否应该保留调试信息以及如何减少调试信息的数量。</li><li>其他Pull Requests包括缓存大小增加、DMA问题、RBD性能优化等。</li></ul></li><li><strong>调试信息</strong>： <ul><li>会议讨论了调试信息的重要性以及如何减少调试信息的数量。</li><li>一些建议包括引入缓存机制、减少不必要的字符串操作以及重新评估日志记录策略。</li></ul></li><li><strong>RocksDB</strong>： <ul><li>讨论了将RocksDB缓存集成到mempool基础设施中的可行性。</li><li>讨论了关于RocksDB内存分配策略的改进。</li></ul></li><li><strong>Ceph性能</strong>： <ul><li>讨论了Ceph性能优化，包括RBD性能优化、对象存储性能优化等。</li><li>讨论了如何减少CPU使用率以及如何提高性能。 <strong>决定的事项</strong>：</li></ul></li><li>接受Radek提交的关于边界代码和编译器优化的Pull Requests。</li><li>继续讨论调试信息的问题，并尝试减少调试信息的数量。</li><li>将RocksDB缓存集成到mempool基础设施中。</li><li>继续优化Ceph性能。 <strong>后续行动计划</strong>：</li><li>Nick将跟进关于调试信息的问题。</li><li>Radek将继续优化RBD性能。</li><li>Sage将继续合并PullRequests。</li><li>其他团队成员将继续进行Ceph性能优化工作。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph相关领域英文关键词，例如： <ul><li>Pull Requests</li><li>RocksDB</li><li>mempool</li><li>RBD</li><li>EC</li><li>SSD</li><li>CPU</li><li>latency</li><li>throughput</li><li>workload</li></ul></li></ul><p>[标签]</p><ul><li>Ceph</li><li>分布式存储</li><li>性能优化</li><li>RocksDB</li><li>调试信息</li></ul>",7)])])}const d=e(s,[["render",r]]);export{c as __pageData,d as default};
